<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Services\MailService;
use OpenLMS\Services\SecretService;
use OpenLMS\Services\SettingsService;

final class SettingsController
{
    public static function index(): void
    {
        Auth::requireAdmin();
        $error=$message=null;
        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!Csrf::validate($_POST['_csrf']??null))$error='Security token expired.';
            else try{
                $action=(string)($_POST['action']??'');
                if($action==='general'){
                    $oldLmsName=app_name();$lmsName=mb_substr(trim((string)($_POST['lms_name']??$oldLmsName)),0,120);if($lmsName==='')throw new \RuntimeException('LMS name is required.');
                    $timezone=(string)($_POST['timezone']??'UTC');
                    if(!in_array($timezone,\DateTimeZone::listIdentifiers(),true))throw new \RuntimeException('Choose a valid timezone.');
                    $maintenance=isset($_POST['maintenance_enabled'])?'1':'0';$maintenanceMessage=mb_substr(trim((string)($_POST['maintenance_message']??'')),0,600);if($maintenanceMessage===''||$maintenanceMessage==='Open LMS is temporarily unavailable for maintenance. Please try again later.'||$maintenanceMessage===$oldLmsName.' is temporarily unavailable for maintenance. Please try again later.')$maintenanceMessage=$lmsName.' is temporarily unavailable for maintenance. Please try again later.';
                    $smtpFromName=(string)SettingsService::get('smtp_from_name','');if($smtpFromName===''||$smtpFromName==='Open LMS'||$smtpFromName===$oldLmsName)SettingsService::set('smtp_from_name',$lmsName);
                    SettingsService::setMany(['institution_name'=>$lmsName,'app_timezone'=>$timezone,'maintenance_enabled'=>$maintenance,'maintenance_message'=>$maintenanceMessage]);
                    date_default_timezone_set($timezone);Auth::audit('settings.general','Updated timezone and maintenance settings');$message='General settings saved.';
                }elseif($action==='smtp'){
                    $enabled=isset($_POST['smtp_enabled']);$host=trim((string)($_POST['smtp_host']??''));$port=(int)($_POST['smtp_port']??587);$enc=(string)($_POST['smtp_encryption']??'tls');$username=trim((string)($_POST['smtp_username']??''));$fromEmail=trim((string)($_POST['smtp_from_email']??''));$fromName=mb_substr(trim((string)($_POST['smtp_from_name']??app_name())),0,160);$password=(string)($_POST['smtp_password']??'');
                    if($enabled){if(!preg_match('/^[A-Za-z0-9.-]+$/',$host))throw new \RuntimeException('SMTP host is invalid.');if($port<1||$port>65535)throw new \RuntimeException('SMTP port is invalid.');if(!filter_var($fromEmail,FILTER_VALIDATE_EMAIL))throw new \RuntimeException('From email is invalid.');}
                    if(!in_array($enc,['tls','ssl','none'],true))$enc='tls';
                    SettingsService::setMany(['smtp_enabled'=>$enabled?'1':'0','smtp_host'=>$host,'smtp_port'=>(string)$port,'smtp_encryption'=>$enc,'smtp_username'=>$username,'smtp_from_email'=>$fromEmail,'smtp_from_name'=>$fromName,'mail_login_alerts_enabled'=>isset($_POST['mail_login_alerts_enabled'])?'1':'0','mail_announcements_enabled'=>isset($_POST['mail_announcements_enabled'])?'1':'0']);
                    if($password!=='')SettingsService::set('smtp_password_secret',SecretService::encrypt($password));
                    if($enabled&&$username!==''&&!SecretService::isConfigured((string)SettingsService::get('smtp_password_secret','')))throw new \RuntimeException('Enter the SMTP password or app password.');
                    Auth::audit('settings.smtp','Updated SMTP and email notification settings');$message='SMTP settings saved.';
                }elseif($action==='smtp_test'){
                    $recipient=trim((string)($_POST['test_recipient']??(Auth::user()['email']??'')));MailService::test($recipient);$message='SMTP test email sent to '.$recipient.'.';Auth::audit('settings.smtp_test','Sent SMTP test email');
                }elseif($action==='payments'){
                    $currency=strtoupper(trim((string)($_POST['payment_currency']??'INR')));if(!preg_match('/^[A-Z]{3}$/',$currency))throw new \RuntimeException('Use a three-letter currency code such as INR.');
                    $razorKey=trim((string)($_POST['razorpay_key_id']??''));$razorSecret=(string)($_POST['razorpay_key_secret']??'');$razorWebhook=(string)($_POST['razorpay_webhook_secret']??'');$stripeSecret=(string)($_POST['stripe_secret_key']??'');$stripeWebhook=(string)($_POST['stripe_webhook_secret']??'');
                    SettingsService::setMany(['payment_currency'=>$currency,'cash_payments_enabled'=>isset($_POST['cash_payments_enabled'])?'1':'0','cash_payment_instructions'=>mb_substr(trim((string)($_POST['cash_payment_instructions']??'')),0,1000),'razorpay_enabled'=>isset($_POST['razorpay_enabled'])?'1':'0','razorpay_key_id'=>$razorKey,'stripe_enabled'=>isset($_POST['stripe_enabled'])?'1':'0']);
                    if($razorSecret!=='')SettingsService::set('razorpay_key_secret',SecretService::encrypt($razorSecret));if($razorWebhook!=='')SettingsService::set('razorpay_webhook_secret',SecretService::encrypt($razorWebhook));if($stripeSecret!=='')SettingsService::set('stripe_secret_key',SecretService::encrypt($stripeSecret));if($stripeWebhook!=='')SettingsService::set('stripe_webhook_secret',SecretService::encrypt($stripeWebhook));
                    if(isset($_POST['razorpay_enabled'])&&($razorKey===''||!SecretService::isConfigured((string)SettingsService::get('razorpay_key_secret',''))))throw new \RuntimeException('Razorpay requires Key ID and Key Secret.');
                    if(isset($_POST['stripe_enabled'])&&!SecretService::isConfigured((string)SettingsService::get('stripe_secret_key','')))throw new \RuntimeException('Stripe requires a Secret Key.');
                    Auth::audit('settings.payments','Updated fee payment gateway settings');$message='Payment settings saved.';
                }
            }catch(\Throwable $e){$error=$e instanceof \RuntimeException?$e->getMessage():'Unable to save settings.';}
        }

        $tz=(string)SettingsService::get('app_timezone','UTC');$zones=\DateTimeZone::listIdentifiers();$groups=[];foreach($zones as $zone){$parts=explode('/',$zone,2);$groups[$parts[0]][]=$zone;}
        $now=new \DateTimeImmutable('now',new \DateTimeZone($tz));$utc=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));
        $smtpSecret=SecretService::isConfigured((string)SettingsService::get('smtp_password_secret',''));$rzSecret=SecretService::isConfigured((string)SettingsService::get('razorpay_key_secret',''));$rzWebhook=SecretService::isConfigured((string)SettingsService::get('razorpay_webhook_secret',''));$stSecret=SecretService::isConfigured((string)SettingsService::get('stripe_secret_key',''));$stWebhook=SecretService::isConfigured((string)SettingsService::get('stripe_webhook_secret',''));
        ob_start();?><div class="page-head"><div><span class="eyebrow">Administration</span><h1>LMS settings</h1><p class="muted">Timezone, maintenance mode, SMTP delivery and payment gateway configuration.</p></div></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
        <section class="card"><div class="section-title"><div><h2>Timezone & server time</h2><p class="muted">Schedules are stored in UTC and entered/displayed in this LMS timezone.</p></div></div><div class="stats-grid"><div class="stat card"><span>LMS time</span><strong class="stat-small" data-live-clock data-timezone="<?=e($tz)?>" data-server-epoch="<?=time()?>"><?=e($now->format('Y-m-d H:i:s'))?></strong><small><?=e($tz)?></small></div><div class="stat card"><span>UTC time</span><strong class="stat-small"><?=e($utc->format('Y-m-d H:i:s'))?></strong><small>Database/storage reference</small></div><div class="stat card"><span>PHP timezone</span><strong class="stat-small"><?=e(date_default_timezone_get())?></strong><small>Runtime timezone</small></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="general"><label>LMS name<input name="lms_name" maxlength="120" value="<?=e(app_name())?>" required><small>Updates the sign-in page, browser title, sidebar and outgoing mail branding.</small></label><label>LMS timezone<select name="timezone" required><?php foreach($groups as $region=>$regionZones):?><optgroup label="<?=e($region)?>"><?php foreach($regionZones as $zone):?><option value="<?=e($zone)?>" <?=$zone===$tz?'selected':''?>><?=e($zone)?></option><?php endforeach;?></optgroup><?php endforeach;?></select><small>India: Asia/Kolkata</small></label><label class="check-row"><input type="checkbox" name="maintenance_enabled" <?=SettingsService::bool('maintenance_enabled')?'checked':''?>> Enable maintenance mode</label><label>Maintenance message<textarea name="maintenance_message" rows="3" maxlength="600"><?=e((string)SettingsService::get('maintenance_message',''))?></textarea><small>Administrators remain unaffected. Other accounts see a maintenance page.</small></label><button class="btn btn-primary">Save general settings</button></form></section>
        <section class="card"><div class="section-title"><div><h2>SMTP email</h2><p class="muted">Works with authenticated SMTP providers that support standard TLS/SSL and AUTH LOGIN.</p></div><span class="badge <?=MailService::enabled()?'badge-ok':'badge-warn'?>"><?=MailService::enabled()?'Configured':'Off'?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="smtp"><label class="check-row"><input type="checkbox" name="smtp_enabled" <?=SettingsService::bool('smtp_enabled')?'checked':''?>> Enable SMTP mail delivery</label><div class="form-row"><label>SMTP host<input name="smtp_host" value="<?=e((string)SettingsService::get('smtp_host',''))?>" placeholder="smtp.example.com"></label><label>Port<input type="number" min="1" max="65535" name="smtp_port" value="<?=e((string)SettingsService::get('smtp_port','587'))?>"></label></div><div class="form-row"><label>Encryption<select name="smtp_encryption"><?php foreach(['tls'=>'STARTTLS','ssl'=>'Implicit SSL/TLS','none'=>'None'] as $v=>$label):?><option value="<?=$v?>" <?=SettingsService::get('smtp_encryption','tls')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>SMTP username / email<input name="smtp_username" value="<?=e((string)SettingsService::get('smtp_username',''))?>" autocomplete="username"></label></div><div class="form-row"><label>Password / app password<input type="password" name="smtp_password" autocomplete="new-password" placeholder="<?=$smtpSecret?'Configured — leave blank to keep':'Enter password'?>"></label><label>From email<input type="email" name="smtp_from_email" value="<?=e((string)SettingsService::get('smtp_from_email',''))?>"></label></div><label>From name<input name="smtp_from_name" maxlength="160" value="<?=e((string)SettingsService::get('smtp_from_name',app_name()))?>"></label><label class="check-row"><input type="checkbox" name="mail_login_alerts_enabled" <?=SettingsService::bool('mail_login_alerts_enabled')?'checked':''?>> Email users after successful sign-in</label><label class="check-row"><input type="checkbox" name="mail_announcements_enabled" <?=SettingsService::bool('mail_announcements_enabled')?'checked':''?>> Allow announcements to be sent by email</label><button class="btn btn-primary">Save SMTP settings</button></form><?php if(MailService::enabled()):?><hr><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="smtp_test"><label>Test recipient<input type="email" name="test_recipient" value="<?=e((string)(Auth::user()['email']??''))?>" required></label><button class="btn">Send test email</button></form><?php endif;?></section>
        <section class="card"><div class="section-title"><div><h2>Fee payment methods</h2><p class="muted">Gateway secrets are encrypted using the LMS application key. Card details stay on provider-hosted checkout pages.</p></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="payments"><label>Currency<input name="payment_currency" maxlength="3" value="<?=e((string)SettingsService::get('payment_currency','INR'))?>" required><small>Use INR for Razorpay.</small></label><details class="settings-panel" open><summary>Cash on counter</summary><label class="check-row"><input type="checkbox" name="cash_payments_enabled" <?=SettingsService::bool('cash_payments_enabled',true)?'checked':''?>> Enable cash-at-counter requests</label><label>Instructions<textarea name="cash_payment_instructions" rows="3" maxlength="1000"><?=e((string)SettingsService::get('cash_payment_instructions',''))?></textarea></label></details><details class="settings-panel"><summary>Razorpay</summary><label class="check-row"><input type="checkbox" name="razorpay_enabled" <?=SettingsService::bool('razorpay_enabled')?'checked':''?>> Enable Razorpay</label><label>Key ID<input name="razorpay_key_id" value="<?=e((string)SettingsService::get('razorpay_key_id',''))?>" placeholder="rzp_test_..."></label><div class="form-row"><label>Key Secret<input type="password" name="razorpay_key_secret" placeholder="<?=$rzSecret?'Configured — leave blank to keep':'Enter secret'?>"></label><label>Webhook Secret<input type="password" name="razorpay_webhook_secret" placeholder="<?=$rzWebhook?'Configured — leave blank to keep':'Optional but recommended'?>"></label></div><p class="hint">Webhook URL: <code><?=e(absolute_app_url('?r=payment-webhook&provider=razorpay'))?></code></p></details><details class="settings-panel"><summary>Stripe</summary><label class="check-row"><input type="checkbox" name="stripe_enabled" <?=SettingsService::bool('stripe_enabled')?'checked':''?>> Enable Stripe Checkout</label><div class="form-row"><label>Secret Key<input type="password" name="stripe_secret_key" placeholder="<?=$stSecret?'Configured — leave blank to keep':'sk_...'?>"></label><label>Webhook Secret<input type="password" name="stripe_webhook_secret" placeholder="<?=$stWebhook?'Configured — leave blank to keep':'whsec_...'?>"></label></div><p class="hint">Webhook URL: <code><?=e(absolute_app_url('?r=payment-webhook&provider=stripe'))?></code></p></details><button class="btn btn-primary">Save payment settings</button></form></section>
        <?php render_page('LMS settings',ob_get_clean());
    }
}
